import {matchPath} from '@docusaurus/router';
import {hasProtocol} from '@docusaurus/isInternalUrl';
import {
  addLeadingSlash,
  addTrailingSlash,
  removeTrailingSlash,
} from '@docusaurus/utils-common';

import type {
  GlobalPluginData,
  GlobalVersion,
  GlobalDoc,
